<?php
require __DIR__ . '/../app/bootstrap.php';
require_login();
$user=current_user();$error='';$ok='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=$_POST['action']??'';
 try{
  if($action==='ubicacion_save'){
   $id=(int)($_POST['id']??0);$nombre=trim($_POST['nombre']??'');$tipo=$_POST['tipo']??'INDEPENDIENTE';
   if($nombre==='')throw new RuntimeException('El nombre de la ubicación es obligatorio.');
   if(!in_array($tipo,['INDEPENDIENTE','MULTIUNIDAD'],true))throw new RuntimeException('Selecciona un tipo de ubicación válido.');
   $data=[$nombre,$tipo,trim($_POST['direccion']??''),trim($_POST['descripcion']??''),($_POST['estado']??'ACTIVA')==='INACTIVA'?'INACTIVA':'ACTIVA'];
   if($id){$data[]=$id;$pdo->prepare('UPDATE ubicaciones SET nombre=?,tipo=?,direccion=?,descripcion=?,estado=? WHERE id=?')->execute($data);$ok='Ubicación actualizada.';}
   else{$pdo->prepare('INSERT INTO ubicaciones(nombre,tipo,direccion,descripcion,estado) VALUES(?,?,?,?,?)')->execute($data);$id=(int)$pdo->lastInsertId();if($tipo==='INDEPENDIENTE')$pdo->prepare("INSERT INTO unidades(ubicacion_id,nombre,tipo,estado) VALUES(?,'Vivienda principal','VIVIENDA','ACTIVA')")->execute([$id]);$ok='Ubicación creada.';}
  }elseif($action==='unidad_save'){
   $id=(int)($_POST['id']??0);$loc=(int)($_POST['ubicacion_id']??0);$nombre=trim($_POST['nombre']??'');$tipo=$_POST['tipo_unidad']??'VIVIENDA';
   if($nombre==='')throw new RuntimeException('El nombre de la unidad es obligatorio.');
   if(!in_array($tipo,['VIVIENDA','HABITACION','LOCAL','OTRA'],true))throw new RuntimeException('Selecciona un tipo de unidad válido.');
   $q=$pdo->prepare("SELECT COUNT(*) FROM ubicaciones WHERE id=?");$q->execute([$loc]);if(!$q->fetchColumn())throw new RuntimeException('Selecciona una ubicación existente.');
   $data=[$loc,$nombre,$tipo,trim($_POST['descripcion_unidad']??''),($_POST['estado_unidad']??'ACTIVA')==='INACTIVA'?'INACTIVA':'ACTIVA'];
   if($id){$data[]=$id;$pdo->prepare('UPDATE unidades SET ubicacion_id=?,nombre=?,tipo=?,descripcion=?,estado=? WHERE id=?')->execute($data);$ok='Unidad actualizada.';}
   else{$pdo->prepare('INSERT INTO unidades(ubicacion_id,nombre,tipo,descripcion,estado) VALUES(?,?,?,?,?)')->execute($data);$ok='Unidad creada.';}
  }elseif($action==='unidad_delete'){
   $id=(int)($_POST['id']??0);$q=$pdo->prepare('SELECT COUNT(*) FROM inquilinos WHERE unidad_id=?');$q->execute([$id]);if((int)$q->fetchColumn())throw new RuntimeException('Esta unidad tiene inquilinos asociados. Reasígnalos antes de eliminarla.');
   $pdo->prepare('DELETE FROM unidades WHERE id=?')->execute([$id]);$ok='Unidad eliminada.';
  }elseif($action==='ubicacion_delete'){
   $id=(int)($_POST['id']??0);$q=$pdo->prepare('SELECT COUNT(*) FROM unidades WHERE ubicacion_id=?');$q->execute([$id]);if((int)$q->fetchColumn())throw new RuntimeException('Esta ubicación todavía contiene unidades. Elimina o mueve sus unidades antes.');
   $pdo->prepare('DELETE FROM ubicaciones WHERE id=?')->execute([$id]);$ok='Ubicación eliminada.';
  }
 }catch(Throwable $e){$error=$e instanceof PDOException?'No se pudo guardar. Comprueba que no haya nombres duplicados.':$e->getMessage();}
}
$editLoc=null;$editUnit=null;
if(isset($_GET['editar_ubicacion'])){$q=$pdo->prepare('SELECT * FROM ubicaciones WHERE id=?');$q->execute([(int)$_GET['editar_ubicacion']]);$editLoc=$q->fetch()?:null;}
if(isset($_GET['editar_unidad'])){$q=$pdo->prepare('SELECT * FROM unidades WHERE id=?');$q->execute([(int)$_GET['editar_unidad']]);$editUnit=$q->fetch()?:null;}
$locations=$pdo->query("SELECT l.*,(SELECT COUNT(*) FROM unidades u WHERE u.ubicacion_id=l.id) unidades,(SELECT COUNT(*) FROM inquilinos t JOIN unidades u ON u.id=t.unidad_id WHERE u.ubicacion_id=l.id) inquilinos FROM ubicaciones l ORDER BY l.estado='ACTIVA' DESC,l.nombre")->fetchAll();
$units=$pdo->query("SELECT u.*,l.nombre ubicacion_nombre,(SELECT COUNT(*) FROM inquilinos t WHERE t.unidad_id=u.id) inquilinos FROM unidades u JOIN ubicaciones l ON l.id=u.ubicacion_id ORDER BY l.nombre,u.nombre")->fetchAll();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ubicaciones e inmuebles · APP Alquileres</title><link rel="stylesheet" href="assets/app.css"></head><body>
<header class="topbar"><a class="brand" href="index.php"><span class="brand-icon">⌂</span><span>APP Alquileres<small>Ubicaciones e inmuebles</small></span></a><a class="btn outline" href="index.php">Volver al inicio</a></header><main class="content">
<div class="page-head"><div><h1>Ubicaciones e inmuebles</h1><p class="muted">Gestiona viviendas independientes o ubicaciones que contienen varias unidades.</p></div></div>
<?php if($ok):?><div class="notice"><?=e($ok)?></div><?php endif;?><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?>
<section class="panel"><div class="page-head"><h3><?=$editLoc?'Editar ubicación':'Nueva ubicación'?></h3><?php if($editLoc):?><a class="btn outline" href="ubicaciones.php">Cancelar</a><?php endif;?></div>
<form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="ubicacion_save"><input type="hidden" name="id" value="<?=e($editLoc['id']??0)?>"><div><label>Nombre *</label><input name="nombre" required value="<?=e($editLoc['nombre']??'')?> "></div><div><label>Tipo de ubicación</label><select name="tipo"><option value="INDEPENDIENTE" <?=($editLoc['tipo']??'INDEPENDIENTE')==='INDEPENDIENTE'?'selected':''?>>Vivienda independiente</option><option value="MULTIUNIDAD" <?=($editLoc['tipo']??'')==='MULTIUNIDAD'?'selected':''?>>Edificio / ubicación con varias unidades</option></select></div><div class="full"><label>Dirección</label><input name="direccion" value="<?=e($editLoc['direccion']??'')?>"></div><div class="full"><label>Descripción / notas</label><textarea name="descripcion" rows="2"><?=e($editLoc['descripcion']??'')?></textarea></div><div><label>Estado</label><select name="estado"><option value="ACTIVA" <?=($editLoc['estado']??'ACTIVA')==='ACTIVA'?'selected':''?>>Activa</option><option value="INACTIVA" <?=($editLoc['estado']??'')==='INACTIVA'?'selected':''?>>Inactiva</option></select></div><div class="full"><button class="btn primary">Guardar ubicación</button></div></form></section>
<section class="panel"><div class="page-head"><h3><?=$editUnit?'Editar unidad':'Añadir unidad'?></h3><?php if($editUnit):?><a class="btn outline" href="ubicaciones.php">Cancelar</a><?php endif;?></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="unidad_save"><input type="hidden" name="id" value="<?=e($editUnit['id']??0)?>"><div><label>Ubicación *</label><select name="ubicacion_id" required><?php foreach($locations as $l):?><option value="<?=$l['id']?>" <?=((int)($editUnit['ubicacion_id']??0)===(int)$l['id'])?'selected':''?>><?=e($l['nombre'])?></option><?php endforeach;?></select></div><div><label>Nombre de la unidad *</label><input name="nombre" required value="<?=e($editUnit['nombre']??'')?> " placeholder="Ej. Piso 1, Habitación A"></div><div><label>Tipo</label><select name="tipo_unidad"><?php foreach(['VIVIENDA'=>'Vivienda','HABITACION'=>'Habitación','LOCAL'=>'Local','OTRA'=>'Otra unidad'] as $v=>$label):?><option value="<?=$v?>" <?=($editUnit['tipo']??'VIVIENDA')===$v?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></div><div><label>Estado</label><select name="estado_unidad"><option value="ACTIVA" <?=($editUnit['estado']??'ACTIVA')==='ACTIVA'?'selected':''?>>Activa</option><option value="INACTIVA" <?=($editUnit['estado']??'')==='INACTIVA'?'selected':''?>>Inactiva</option></select></div><div class="full"><label>Descripción</label><textarea name="descripcion_unidad" rows="2"><?=e($editUnit['descripcion']??'')?></textarea></div><div class="full"><button class="btn primary">Guardar unidad</button></div></form></section>
<section class="panel"><h3>Ubicaciones registradas</h3><div class="table-wrap"><table><tr><th>Ubicación</th><th>Tipo</th><th>Dirección</th><th>Unidades</th><th>Inquilinos</th><th>Estado</th><th>Acciones</th></tr><?php foreach($locations as $l):?><tr><td><?=e($l['nombre'])?></td><td><?=$l['tipo']==='INDEPENDIENTE'?'Vivienda independiente':'Varias unidades'?></td><td><?=e($l['direccion'])?></td><td><?=$l['unidades']?></td><td><?=$l['inquilinos']?></td><td><?=e($l['estado'])?></td><td class="actions"><a class="btn outline" href="ubicaciones.php?editar_ubicacion=<?=$l['id']?>">Editar</a><?php if((int)$l['unidades']===0):?><form method="post" onsubmit="return confirm('¿Eliminar ubicación?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="ubicacion_delete"><input type="hidden" name="id" value="<?=$l['id']?>"><button class="btn danger">Borrar</button></form><?php endif;?></td></tr><?php endforeach;?><?php if(!$locations):?><tr><td colspan="7" class="empty">Todavía no hay ubicaciones.</td></tr><?php endif;?></table></div></section>
<section class="panel"><h3>Unidades</h3><div class="table-wrap"><table><tr><th>Unidad</th><th>Ubicación</th><th>Tipo</th><th>Inquilinos</th><th>Estado</th><th>Acciones</th></tr><?php foreach($units as $u):?><tr><td><?=e($u['nombre'])?></td><td><?=e($u['ubicacion_nombre'])?></td><td><?=e($u['tipo'])?></td><td><?=$u['inquilinos']?></td><td><?=e($u['estado'])?></td><td class="actions"><a class="btn outline" href="ubicaciones.php?editar_unidad=<?=$u['id']?>">Editar</a><?php if((int)$u['inquilinos']===0):?><form method="post" onsubmit="return confirm('¿Eliminar unidad?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="unidad_delete"><input type="hidden" name="id" value="<?=$u['id']?>"><button class="btn danger">Borrar</button></form><?php endif;?></td></tr><?php endforeach;?><?php if(!$units):?><tr><td colspan="6" class="empty">Todavía no hay unidades.</td></tr><?php endif;?></table></div></section>
<footer>APP Alquileres · Gestión multiubicación</footer></main></body></html>